(function (global, factory) {
  if (typeof define === "function" && define.amd) {
    define([], factory);
  } else if (typeof exports !== "undefined") {
    factory();
  } else {
    var mod = {
      exports: {}
    };
    factory();
    global.indexLoading = mod.exports;
  }
})(typeof globalThis !== "undefined" ? globalThis : typeof self !== "undefined" ? self : this, function () {
  "use strict";

  /**
   * LOINGS - 生成loding条
   * num - 生成的loding条数量
   * timer - loading条变化的速度
   *
   */
  class LODINGS {
    constructor(isClick = false, num = 5, timer = null) {
      this.isClick = isClick;
      // 动画样式
      this.num = num;
      this.colors = ["#5eb7b7", "#96d1c7", "#fc7978", "#ffafb0", "#dfddc7"];
      // dom元素
      this.obj = null;
      this.container = null;
      // 动画loadingtimer
      this.timer = null;
      this.time = 380;
    }
    /* 初始化 建立maskDom元素，背景透明黑色 */
    inits() {
      const objStyle = {
        width: "100%",
        height: "100%",
        position: "fixed",
        top: 0,
        left: 0,
        zIndex: 9999999,
        backgroundColor: "#434343"
      };
      this.obj = this.createDom("div", objStyle);
      this.obj.className = "loading-dc";
      document.getElementsByTagName("html")[0].append(this.obj);
      this.createContainer();
      if (this.isClick) {
        const _this = this;
        this.obj.addEventListener("click", e => {
          if (e.target.className === "loading-dc") {
            // 去冒泡行为
            _this.clean();
          }
        }, false);
      }
    }
    /* 创建LodingDOM父级元素 */
    createContainer() {
      const wid = this.num * 10;
      const style = {
        width: wid + "px",
        height: "30px",
        display: "flex",
        marginLeft: "calc(50vw - " + wid / 2 + "px)",
        marginTop: "calc(50vh - 15px)"
      };
      this.container = this.createDom("div", style);
      this.obj.appendChild(this.container);
      for (let i = 0; i < this.num; i++) {
        this.createLoadingDom(i);
      }
      this.loadingActive();
    }
    /* 创建DOM以及css样式赋值 */
    createDom(node, style = {}) {
      const obj = document.createElement(node);
      for (var key in style) {
        obj.style[key] = style[key];
      }
      return obj;
    }

    /* 创建loding动画 */
    createLoadingDom(inv) {
      const style = {
        width: "5px",
        height: "30px",
        marginRight: "5px",
        borderRadius: "2px",
        position: "relative",
        top: 0,
        left: 0,
        transition: "height .25s, top .25s",
        backgroundColor: this.colors[inv]
      };
      const loadings = this.createDom("div", style);
      this.container.appendChild(loadings);
    }

    /* loading动画设置 */
    loadingActive() {
      let num = 0;
      this.timer = setInterval(() => {
        Array.from(this.container.children).map((t, i) => {
          t.style.height = i === num ? "40px" : "30px";
          t.style.top = i === num ? "-5px" : "0px";
        });
        num = num === 4 ? 0 : num + 1;
      }, this.time);
    }

    /* 清理dom和func，time最少加载1s */
    clean(time = 1500) {
      clearInterval(this.timer);
      Array.from(this.container.childNodes).map(t => {
        this.container.removeChild(t);
      });
      this.container.remove();
      this.obj.remove();
      this.obj = null;
      this.container = null;
      this.timer = null;
      this.time = 380;
    }
  }

  /** loading的结束函数，判断页面加载周期，开启/关闭loading, 默认10ms检测一次 **/
  const AsyncLoadingTimer = async (LD = null) => {
    console.log(document.readyState);
    switch (document.readyState) {
      case "loading":
        // 第一次加载
        if (LD === null) {
          LD = new LODINGS();
          LD.inits();
        }
        await delay(500);
        AsyncLoadingTimer(LD);
        break;
      case "interactive":
        // 第一次加载
        if (LD === null) {
          LD = new LODINGS();
          LD.inits();
        }
        await delay(500);
        AsyncLoadingTimer(LD);
        break;
      case "complete":
        if (LD) LD.clean();
        break;
      default:
        return;
    }
  };

  /* 延迟执行 */
  const delay = (time = 10) => {
    return new Promise(resolve => {
      const timer = setTimeout(() => {
        clearTimeout(timer);
        resolve();
      }, time);
    });
  };
  module.exports = function () {
    AsyncLoadingTimer();
  };
});
